-- Transaction-scoped fixtures: never run against production.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select is((select count(*) from auth.users),0::bigint,'fresh database contains zero auth users');
select is((select count(*) from profiles),0::bigint,'fresh database contains zero profiles');
select is((select count(*) from club_memberships),0::bigint,'fresh database contains zero memberships');
select is((select count(*) from activities),0::bigint,'fresh database contains zero activities');
select is((select count(*) from club_sessions),0::bigint,'fresh database contains zero sessions');
select is((select count(*) from session_rsvps),0::bigint,'fresh database contains zero RSVPs');
select is((select count(*) from health_connections),0::bigint,'fresh database contains zero health connections');
select is((select count(*) from race_results),0::bigint,'fresh database contains zero race results');
select is((select count(*) from clubs),1::bigint,'exactly one initial club');
select is((select count(*) from pg_tables where schemaname in ('public','runtrack_private') and not rowsecurity),0::bigint,'all application tables enforce RLS');
select is((select name from clubs),'Tyne Bridge Harriers','initial club identity');
select is((select status from clubs),'active','initial club is active');
select ok((public.bootstrap_status()->>'setup_required')::boolean,'missing bootstrap email fails closed');
select is((public.before_user_created('{"user":{"email":"owner@example.test"}}')->'error'->>'http_code'),'503','auth hook rejects missing configuration');
select public.configure_bootstrap_owner('owner@example.test');
select is(public.before_user_created('{"user":{"email":" OWNER@example.test "}}'),'{}'::jsonb,'hook normalizes owner email');
select is((public.before_user_created('{"user":{"email":"attacker@example.test","user_metadata":{"email":"owner@example.test","role":"admin"}}}')->'error'->>'http_code'),'403','hook rejects metadata spoofing and other signups');
select is((public.before_user_created('{"user":{}}')->'error'->>'http_code'),'403','hook rejects absent email');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
 ('11111111-1111-4111-8111-111111111111','owner@example.test',now(),'{"display_name":"Owner"}'),
 ('22222222-2222-4222-8222-222222222222','athlete@example.test',now(),'{"role":"admin","display_name":"Runner"}'),
 ('33333333-3333-4333-8333-333333333333','unverified@example.test',null,'{}');
select is((select count(*) from profiles),0::bigint,'signup does not depend on a profile trigger');
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select throws_ok('select public.ensure_profile()', '42501','Verify your email before continuing','unverified user cannot create profile');
select throws_ok($$select public.join_club('TBHRTA')$$, '42501','Verify your email before joining a club','unverified user cannot bootstrap');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select lives_ok('select public.ensure_profile()', 'verified athlete profile created');
select is((public.join_club('TBHRTA')->>'code'),'bootstrap_restricted','code alone cannot bootstrap non-owner');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok('select public.ensure_profile()', 'verified owner profile created');
select lives_ok('select public.ensure_profile()', 'profile creation is idempotent');
select is((public.join_club('WRONG!')->>'code'),'invalid_code','invalid code rejected');
select is((select count(*) from club_memberships),0::bigint,'invalid code creates no membership');
select is((public.join_club(' tbhrta ')->>'role'),'admin','verified configured owner plus valid normalized code bootstraps');
select is((public.join_club('TBHRTA')->>'role'),'admin','bootstrap retry is idempotent');
select is((select count(*) from club_memberships),1::bigint,'duplicate owner join creates no duplicate');
select ok(not (public.bootstrap_status()->>'bootstrap_pending')::boolean,'bootstrap completed');
select throws_ok($$select public.configure_bootstrap_owner('new@example.test')$$,'42501','permission denied for function configure_bootstrap_owner','browser cannot alter protected owner email');
select throws_ok($$select * from runtrack_private.club_join_codes$$,'42501','permission denied for table club_join_codes','browser cannot enumerate private join codes');
select throws_ok($$select * from runtrack_private.application_settings$$,'42501','permission denied for table application_settings','browser cannot read owner configuration');
select throws_ok($$select public.before_user_created('{}')$$,'42501','permission denied for function before_user_created','browser cannot call privileged auth hook');
select lives_ok($$select public.update_onboarding('{"health_step":2}')$$,'owner can save onboarding progress');
select is((select onboarding->>'health_step' from profiles),'2','onboarding persists');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from profiles),1::bigint,'profile RLS hides other users');
select is((public.join_club('TBHRTA')->>'role'),'athlete','postbootstrap member cannot inherit admin');
select throws_ok($$insert into race_results(user_id,event_name,event_date,distance_m,duration_s) values(auth.uid(),'Finite race',current_date,'NaN',1200)$$,'23514',null,'non-finite race measurements rejected by database');
select throws_ok($$insert into race_results(user_id,event_name,event_date,distance_m,duration_s) values(auth.uid(),' ',current_date,5000,1200)$$,'23514',null,'empty race names rejected by database');
select is((public.join_club('tbhrta')->>'role'),'athlete','repeat athlete join preserves athlete role');
select throws_ok($$insert into club_memberships(club_id,user_id,role) values('74796e65-6272-4964-8765-686172726965','22222222-2222-4222-8222-222222222222','admin')$$,'42501','permission denied for table club_memberships','direct membership insertion denied');
select throws_ok($$update club_memberships set role='admin' where user_id=auth.uid()$$,'42501','permission denied for table club_memberships','self promotion denied');
select throws_ok($$select public.update_membership((select id from club_memberships where role='admin'),'active','athlete')$$,'42501','Club administrator required','athlete cannot alter another membership through RPC');
select throws_ok($$select public.rotate_join_code('74796e65-6272-4964-8765-686172726965','HACKED')$$,'42501','Club administrator required','athlete cannot rotate code');
select throws_ok($$insert into club_sessions(club_id,title,starts_at,created_by) values('74796e65-6272-4964-8765-686172726965','Unauthorized',now(),auth.uid())$$,'42501','new row violates row-level security policy for table "club_sessions"','athlete cannot create club session');
reset role;
select is(public.before_user_created('{"user":{"email":"new@example.test"}}'),'{}'::jsonb,'public registration available after bootstrap');
-- These additional identities and the second club exist in this rollback-only test transaction.
insert into clubs(id,name) values('44444444-4444-4444-8444-444444444444','Isolated test club');
insert into club_sessions(id,club_id,title,starts_at,created_by) values('55555555-5555-4555-8555-555555555555','74796e65-6272-4964-8765-686172726965','Real session',now()+interval '1 day','11111111-1111-4111-8111-111111111111');
insert into club_sessions(id,club_id,title,starts_at) values('66666666-6666-4666-8666-666666666666','44444444-4444-4444-8444-444444444444','Other club session',now());
insert into session_rsvps(session_id,user_id) values('66666666-6666-4666-8666-666666666666','11111111-1111-4111-8111-111111111111');
insert into activities(id,user_id,provider,provider_workout_id,started_at,ended_at,distance_m,active_duration_s,elapsed_duration_s,average_heart_rate) values
 ('77777777-7777-4777-8777-777777777777','11111111-1111-4111-8111-111111111111','google_health','workout-a',now()-interval '1 hour',now(),5000,1500,3600,140);
insert into health_connections(id,user_id,provider,status) values('88888888-8888-4888-8888-888888888888','11111111-1111-4111-8111-111111111111','google_health','connected');
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from clubs),1::bigint,'cross club access denied');
select is((select count(*) from club_sessions),1::bigint,'cross club sessions hidden');
select is((select count(*) from activities),0::bigint,'cross user private activities hidden');
select is((select count(*) from health_connections),0::bigint,'cross user health connections hidden');
select throws_ok($$insert into session_rsvps(session_id,user_id) values('66666666-6666-4666-8666-666666666666',auth.uid())$$,'42501','new row violates row-level security policy for table "session_rsvps"','cannot RSVP to other club');
select lives_ok($$insert into session_rsvps(session_id,user_id) values('55555555-5555-4555-8555-555555555555',auth.uid())$$,'member can RSVP');
select is((select status from session_rsvps where user_id=auth.uid()),'going','RSVP persists');
select lives_ok($$update session_rsvps set status='cancelled' where user_id=auth.uid()$$,'member can cancel RSVP');
select is((select status from session_rsvps where user_id=auth.uid()),'cancelled','RSVP cancellation persists');
select throws_ok($$update session_rsvps set attended=true where user_id=auth.uid()$$,'42501','permission denied for table session_rsvps','athlete cannot fabricate attendance');
select throws_ok($$update activities set distance_m=99999$$,'42501','permission denied for table activities','athlete cannot change imported distance');
select throws_ok($$select public.health_credentials_get('88888888-8888-4888-8888-888888888888')$$,'42501','permission denied for function health_credentials_get','athlete cannot read encrypted credentials');
select throws_ok($$select public.consume_health_oauth_state('spoof')$$,'42501','permission denied for function consume_health_oauth_state','athlete cannot consume OAuth state');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is((select count(*) from activities),1::bigint,'athlete can read own private workout');
select throws_ok($$select public.record_attendance((select id from session_rsvps where user_id='22222222-2222-4222-8222-222222222222'),true)$$,'P0001','Attendance can only be confirmed after a session starts for a runner who is going','future or cancelled RSVP cannot earn confirmed attendance');
select lives_ok($$update club_sessions set starts_at=now()-interval '1 hour' where id='55555555-5555-4555-8555-555555555555'$$,'administrator can correct session time');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
update session_rsvps set status='going' where user_id=auth.uid();
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$select public.record_attendance((select id from session_rsvps where user_id='22222222-2222-4222-8222-222222222222'),true)$$,'administrator can confirm past attendance');
select lives_ok($$update activities set visibility='club',shared_club_id='74796e65-6272-4964-8765-686172726965' where id='77777777-7777-4777-8777-777777777777'$$,'activity sharing is explicit');
select throws_ok($$update activities set visibility='club',shared_club_id='44444444-4444-4444-8444-444444444444' where id='77777777-7777-4777-8777-777777777777'$$,'42501','new row violates row-level security policy for table "activities"','cannot share into another club');
select throws_ok($$select public.update_membership((select id from club_memberships where user_id=auth.uid()),'removed','athlete')$$,'P0001','The club must retain an administrator','final administrator cannot demote themselves');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from activities),0::bigint,'shared workout still hides raw health record');
select is((select count(*) from public.shared_activity_feed('74796e65-6272-4964-8765-686172726965')),1::bigint,'explicit shared activity appears in sanitized feed');
select ok(not (select to_jsonb(f) ? 'average_heart_rate' from public.shared_activity_feed('74796e65-6272-4964-8765-686172726965') f limit 1),'shared activity projection excludes sensitive health measurements');
select is((select count(*) from public.shared_activity_feed('44444444-4444-4444-8444-444444444444')),0::bigint,'shared feed respects club boundary');
select is((select count(*) from public.club_member_profiles('74796e65-6272-4964-8765-686172726965')),2::bigint,'club roster exposes only permitted names');
select is((select count(*) from public.club_member_profiles('44444444-4444-4444-8444-444444444444')),0::bigint,'roster respects club boundary');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$select public.update_membership((select id from club_memberships where user_id='22222222-2222-4222-8222-222222222222'),'removed','athlete')$$,'administrator can remove an athlete');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from session_rsvps),1::bigint,'removed athlete keeps only their own RSVP history without cross-club records');
select is((select count(*) from session_rsvps where attended),1::bigint,'trusted attendance remains available for achievements after leaving club');
select is((select count(*) from club_sessions),0::bigint,'historical RSVP access does not expose former club sessions');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select lives_ok($$select public.update_membership((select id from club_memberships where user_id='22222222-2222-4222-8222-222222222222'),'active','admin')$$,'current administrator can appoint another administrator');
select lives_ok($$select public.update_membership((select id from club_memberships where user_id=auth.uid()),'removed','athlete')$$,'administrator can leave after appointing successor');
select throws_ok($$select public.rotate_join_code('74796e65-6272-4964-8765-686172726965','HACKED')$$,'42501','Club administrator required','removed administrator cannot rotate code');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is((select count(*) from public.shared_activity_feed('74796e65-6272-4964-8765-686172726965')),0::bigint,'removed athlete previous shares no longer appear to club');
select is((select count(*) from public.club_member_profiles('74796e65-6272-4964-8765-686172726965')),2::bigint,'administrators can see minimal names of removed members for management');
reset role;
-- Durable invalid-code counters cannot be rolled back through exception handling.
update runtrack_private.join_attempts set attempts=0 where user_id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
do $$begin for i in 1..10 loop perform public.join_club('INVALID'); end loop; end$$;
select is((public.join_club('TBHRTA')->>'code'),'rate_limited','ten invalid attempts persist and rate limit subsequent calls');
reset role;
-- Auth deletion cascades all personal records, including provider token ciphertext.
insert into runtrack_private.health_credentials(connection_id,access_token_ciphertext,expires_at) values('88888888-8888-4888-8888-888888888888','encrypted-test',now()+interval '1 hour');
delete from auth.users where id='11111111-1111-4111-8111-111111111111';
select is((select count(*) from activities),0::bigint,'account deletion removes personal activities');
select is((select count(*) from runtrack_private.health_credentials),0::bigint,'account deletion removes provider credentials');
select ok(not (select bootstrap_pending from runtrack_private.bootstrap_state),'account deletion cannot reopen bootstrap');
select * from finish();
rollback;
